    '请围绕资料《{name}》展开对话。': '資料「{name}」について会話してください。',
    '用户从资料库选择了这份文件，请使用实际可读取的附件回答；如果附件不可读取，请明确说明。': 'ユーザーが資料ライブラリからこのファイルを選びました。実際に読み取れる添付を使って答えてください。添付を読み取れない場合は、その旨を明確に伝えてください。',
    '请帮我创建一张图像。请先询问我想要的主题、风格、尺寸和用途，然后开始创作。完成后提醒我可以将成果保存到资料库。': '画像を作成してください。まず欲しいテーマ・スタイル・サイズ・用途を尋ねてから制作を始めてください。完成したら成果物を資料ライブラリへ保存できることを教えてください。',
    '请帮我创建一份文档。请先询问文档主题、结构、语气和格式，然后开始撰写。完成后提醒我可以将成果保存到资料库。': 'ドキュメントを作成してください。先にテーマ・構成・トーン・形式を尋ねてから執筆を始めてください。完成したら成果物を資料ライブラリへ保存できることを教えてください。',
    '请帮我创建一份电子表格。请先询问数据字段、计算规则和展示方式，然后开始制作。完成后提醒我可以将成果保存到资料库。': '表計算を作成してください。先にデータ項目・計算ルール・見せ方を尋ねてから作成を始めてください。完成したら成果物を資料ライブラリへ保存できることを教えてください。',
    '请帮我创建一份演示文稿。请先询问主题、受众、页数和风格，然后开始制作。完成后提醒我可以将成果保存到资料库。': 'プレゼンテーションを作成してください。先にテーマ・聴衆・枚数・スタイルを尋ねてから作成を始めてください。完成したら成果物を資料ライブラリへ保存できることを教えてください。',
    '用户从资料库点击了“{kind}”新建入口，请按用户需求完成创作，并提醒用户可将成果保存到资料库。': 'ユーザーが資料ライブラリの「{kind}」新規作成を選びました。ユーザーの要望どおりに制作し、成果物を資料ライブラリへ保存できることを伝えてください。',
