    '对话入口尚未就绪，请稍后重试；也可以选择手动录入。': '対話エントリはまだ準備ができていません。しばらくしてから再試行するか、手動で入力してください。',
    '请在对话中描述需求，发送后确认标题、背景和完成标准。': '対話で課題を説明し、送信後にタイトル・背景・完了基準をご確認ください。',
    '对话暂时没有打开，请重试；也可以选择手动录入。': '対話を開けませんでした。再試行するか、手動で入力してください。',
    '当前客户端不支持提交验收，请更新后重试。': 'このクライアントはまだ受け入れ確認の提出に対応していません。クライアントを更新してから再試行してください。',
    '当前客户端不支持验收，请更新后重试。': 'このクライアントはまだ受け入れ確認に対応していません。クライアントを更新してから再試行してください。',
    '当前组织没有可分享的其他成员': 'この組織に共有できる他のメンバーがいません',
