    '文件已保存': 'ファイルを保存しました',
    '执行会话在另一台设备上；在这条需求的详情里核对证据并确认即可。': '実行セッションは別の端末にあります。課題の詳細にある受け入れ確認カードで証拠を確認して承認できます。',
    '打开需求失败：{value1}': '課題を開けませんでした：{value1}',
    '移动到…': '移動先…',
    '未选择需求': '課題が未選択',
    '搜索连接器、系统或服务': 'コネクター・システム・サービスを検索',
    '公司还没有发布可用连接': '会社が公開している接続はまだありません',
    '从可信模板开始，或接入一个已知的 HTTP 连接地址。': '信頼できるテンプレートから始めるか、既知の HTTP 接続先を取り込みます。',
    '公司尚未开放连接执行能力。': '会社側でまだ接続実行が有効になっていません。',
    '全部执行席位 · 点击需求打开 AI 工作详情': 'すべての Agent 席 · 課題をクリックして AI 作業の詳細を開く',
    '切换到全部席位查看其他需求，或从需求池中安排新的工作。': 'すべての Agent 席に切り替えると他の課題を表示できます。課題プールから新しい仕事を割り当てることもできます。',
    '按需求状态筛选': '課題のステータスで絞り込み',
    '你可以先配置连接；管理员开放工具后，任务才会调用。': '接続は先に設定できます。タスクが呼び出すのは管理者がツールを開放した後です。',
    '加快安装文件校验，将旧版本清理移到后台，减少更新完成前的等待。': 'インストール検証を高速化し、旧バージョンのクリーンアップをバックグラウンドに移して、更新完了までの待ち時間を短縮しました。',
    '完善更新状态上报的超时与进度合并，避免网络响应拖住升级流程。': '更新ステータス報告のタイムアウトと進捗の統合を改善し、ネットワーク応答がアップグレードの流れを滞らせないようにしました。',
    '修复更新期间启动入口短暂不可用的问题，文件被占用或更新中断时保留原有入口。': '更新中に起動入口が一時的に使えなくなる問題を修正。ファイルがロック中でも更新が中断されても元の入口を保持します。',
    '整理插件、连接器、MCP、技能和市场页面，统一字号、卡片与操作位置，保留原有彩色图标。': 'プラグイン・コネクター・MCP・スキル・市場ページを整理し、フォントサイズ・カード・操作位置を統一しました（従来のカラーアイコンは維持）。',
    '保留我的申请入口，简化各页添加菜单，常用连接模板默认收起并支持搜索展开。': '「申請履歴」入口を保持し、各ページの追加メニューを簡素化。よく使う接続テンプレートはデフォルトで折りたたみ、検索で展開できます。',
    '修复工具超时后仍占用会话、继续和引导无法推进的问题；确认执行退出后再继续下一轮。': 'ツールのタイムアウト後にセッションを占有し続け、継続やガイドが進めなくなる問題を修正。実行が終了してから次のラウンドに進みます。',
    '补齐工具执行时限，取消当前操作时保护已有后台任务与其他请求。': 'ツール実行の制限時間を補完し、現在の操作をキャンセルしても既存のバックグラウンドタスクや他のリクエストを保護します。',
    '升级改用紧凑的单一进度窗口，按实际解包和校验进度展示百分比。': 'アップグレードはコンパクトな単一進捗ウィンドウに切り替え、実際の解凍と検証の進捗をパーセントで表示します。',
    '优化安装校验与旧版本整理效率，保留已有会话、文件及回退能力。': 'インストール検証と旧バージョン整理の効率を改善し、既存の会話・ファイル・ロールバック機能を保持します。',
    '更新时显示下载、校验及安装阶段，支持等待工作结束后重启；升级过程中再次打开 SoduWork 会等待安装完成。': '更新中にダウンロード・検証・インストールの段階を表示し、作業完了後の再起動に対応。アップグレード中に SoduWork を再度開くとインストール完了を待ちます。',
    '修复引导消息遗漏或重复、技能未随消息发送等问题，增强对话恢复与模型页面加载的稳定性。': 'ガイドメッセージの欠落・重複や、スキルがメッセージと一緒に送られない問題を修正し、会話復元とモデルページ読み込みの安定性を向上しました。',
    '优化插件安装、窗口菜单、窄屏对话栏和文件预览，改善主题配色与界面可读性。': 'プラグインインストール・ウィンドウメニュー・狭い画面の会話バー・ファイルプレビューを改善し、テーマ配色と可読性を向上しました。',
    '完善电脑操作时的桌面提示，并缩小 AI 团队顶部的智能体卡片。': 'PC 操作中のデスクトップ通知を改善し、AI チーム上部の Agent カードを縮小しました。',
