    '私钥口令（可选）': '秘密鍵のパスフレーズ（省略可）',
    '凭据只在当前客户端加密保存，不会上传到 SoduWork 服务，也不会出现在日志或会话内容中。连接测试通过后才会保存；首次成功连接会记录 SSH 主机指纹，后续连接会校验它。登录账号需要具备安装 Runner 的权限（root，或可以无交互执行 sudo）。': '認証情報は現在のクライアントに暗号化して保存され、SoduWork サービスへアップロードされず、ログや会話内容にも現れません。接続テストの合格後に保存され、初回の接続成功時に SSH ホストのフィンガープリントを記録し、以後の接続で照合します。サインインアカウントには Runner をインストールできる権限（root、または対話なしで sudo を実行できること）が必要です。',
