    '请在目标电脑终端执行下方命令，完成后回到这里检查连接。': '対象 PC のターミナルで下記のコマンドを実行し、完了したらここに戻って接続を確認してください。',
    '无法复制，请手动选中命令复制': 'コピーできませんでした。コマンドを手動で選択してコピーしてください',
    '尚未连接，请确认 Runner 已启动并能访问 SoduWork 服务': '未接続です。Runner が起動しており、SoduWork サービスに到達できることを確認してください',
    '当前客户端不支持云端电脑连接，请升级后重试': 'このクライアントはクラウド PC 接続に未対応です。更新してから再試行してください',
    '无法连接云端电脑，请检查地址、端口和登录信息': 'クラウド PC に接続できません。アドレス・ポート・サインイン情報を確認してください',
